    function haltForAccountLocked(reason) {
        clearLoopActive("haltForAccountLocked:" + reason);
        localStorage.removeItem("tw_pending_assignment");
        localStorage.removeItem("tw_refresh_pending");
        localStorage.removeItem("tw_farm_loop_active");
        localStorage.removeItem("tw_next_farm_burst_at");
        localStorage.removeItem("tw_next_recheck_at");
        localStorage.removeItem("tw_load_farmgod");
        localStorage.removeItem("tw_load_farmgod_capped");

        if (wakeLockSentinel) {
            wakeLockSentinel.release().catch(() => {});
            wakeLockSentinel = null;
        }

        const dimEl = document.getElementById("tw-dim-overlay");
        if (dimEl) dimEl.remove();

        if (!accountLockedHandled) {
            accountLockedHandled = true;

            const expiry = extractLockExpiry();

            console.warn("[TW] ACCOUNT GESPERRT - alle automatisierten Vorgaenge gestoppt.", reason, expiry);
            showAccountLockedBanner(expiry);

            if (shouldPlayBotSound()) {
                playBotProtectionAlertSound();
            }

            sendDiscordNotification(
                "🔒 Account gesperrt",
                `Der Account wurde wegen automatisierter Spielaktionen gesperrt.\n` +
                (expiry ? `Ablauf der Sperre: ${expiry}\n` : "") +
                `Hinweis: Der Account kann während der Sperre weiterhin angegriffen werden - manuelle Prüfung empfohlen.`,
                0x6a0dad
            );
        }
    }

    function startAccountLockWatchdog() {
        setInterval(() => {
            if (isAccountLocked()) {
                haltForAccountLocked("watchdog");
            }
        }, 2000);
    }

    startAccountLockWatchdog();

    let sessionLoggedOutHandled = false;

    // === Abmeldeerkennung mit zwei Guetegraden (31.08.2026) ==========
    //
    // Fehlalarm vom 31.08. 17:06:35: "SESSION BEENDET" waehrend einer
    // ganz normalen Sitzung. Der Stacktrace kam aus einem message-Handler
    // des Spiels, also aus einem AJAX-Seitenwechsel, und sechs Sekunden
    // spaeter lief GodBot wieder normal. Ausgeloest hatte es kurz nach
    // dem Manager-Durchlauf um 17:05:28 - der wechselt reihum durch alle
    // Doerfer, also viele Wechsel kurz hintereinander.
    //
    // Grund: game_data ist seit dem Umbau ein Getter auf das Seitenglobal.
    // Waehrend eines Wechsels ist das fuer einen Moment weg oder wird
    // gerade ersetzt - der Getter liefert dann null. Vorher, beim direkten
    // Zugriff, war dieses Zeitfenster nicht sichtbar.
    //
    // Die alte Pruefung behandelte beide Anzeichen gleich. Sie sind aber
    // nicht gleich viel wert:
    //
    //   Passwortfeld auf der Seite  -> eindeutig. Eine Anmeldemaske
    //                                  erscheint nicht aus Versehen.
    //   game_data fehlt             -> schwach. Kann ein Augenblick
    //                                  mitten im Seitenwechsel sein.
    //
    // Dazu ein Gegenbeleg: steht #ds_body noch im Dokument, sind wir auf
    // einer Spielseite und gerade nicht abgemeldet. Der Marker ist in
    // beiden echten Seitenquellen belegt - Botschutzseite (Desktop) und
    // Versammlungsplatz (Mobil). #menu_row waere falsch gewesen, das gibt
    // es nur im Desktop-Aufbau.
    function sessionAbmeldeSignal() {
        try {
            // 31.08.2026: NUR FREMDE Passwortfelder zaehlen.
            //
            // GodBot bringt selbst welche mit - seit heute
            // #tw-captcha-apikey fuer den Botschutz-Schluessel, dazu
            // #tw-gate-admin-pw. Stand der Einstellungsbereich offen,
            // fand die Pruefung das eigene Feld und meldete
            // "Anmeldemaske auf der Seite".
            //
            // Belegt im Protokoll vom 31.08.: um 18:23:47 "SESSION
            // BEENDET", und zwei Sekunden spaeter schickt der Raubzug
            // Slot 3 Welle 3 los. Um 18:24:02 war der Verdacht "wieder
            // ausgeraeumt" - genau als das Fenster zuging.
            //
            // Verschaerft wurde es durch meine eigene Aenderung von
            // vorhin: das Passwortfeld gilt seither als EINDEUTIGES
            // Anzeichen und stoppt nach 30 statt 90 Sekunden.
            //
            // Ausgeschlossen wird ueber das Praefix "tw-", das alle
            // GodBot-Elemente tragen - am Element selbst oder an einem
            // Vorfahren, damit auch kuenftige Felder ohne eigene Kennung
            // erfasst sind.
            const fremdesPasswortfeld =
                Array.from(document.querySelectorAll('input[type="password"]'))
                    .some(el => !el.closest('[id^="tw-"]'));

            if (fremdesPasswortfeld) {
                return { aus: true, sicher: true, grund: "Anmeldemaske auf der Seite" };
            }

            const spielSeite = !!document.getElementById("ds_body");

            if (typeof game_data === "undefined" || !game_data || !game_data.player) {
                return {
                    aus: true,
                    sicher: false,
                    grund: spielSeite
                        ? "game_data fehlt, die Spielseite steht aber noch"
                        : "game_data fehlt und keine Spielseite erkennbar"
                };
            }
        } catch (e) {
            return { aus: true, sicher: false, grund: "Prüfung nicht durchführbar: " + e };
        }
        return { aus: false, sicher: false, grund: "" };
    }

    // Bleibt fuer die uebrigen Aufrufer erhalten.
    function isSessionLoggedOut() {
        return sessionAbmeldeSignal().aus;
    }

