function extractScavengeOptionsConfig(doc) {
    const scriptText = [...doc.scripts]
        .map(s => s.textContent)
        .find(t => t.includes("new ScavengeScreen("));

    if (!scriptText) {
        console.warn("[TW] ScavengeScreen-Konfiguration nicht gefunden.");
        return null;
    }

    const marker = "new ScavengeScreen(";
    const argStart = scriptText.indexOf(marker) + marker.length;

    let depth = 0;
    let objStart = -1;
    let objEnd = -1;

    for (let i = argStart; i < scriptText.length; i++) {
        if (scriptText[i] === "{") {
            if (depth === 0) objStart = i;
            depth++;
        }
        if (scriptText[i] === "}") {
            depth--;
            if (depth === 0) {
                objEnd = i + 1;
                break;
            }
        }
    }

    if (objStart < 0 || objEnd < 0) {
        console.warn("[TW] Konnte ScavengeScreen-Optionen-Objekt nicht abgrenzen.");
        return null;
    }

    try {
        return JSON.parse(scriptText.slice(objStart, objEnd));
    } catch (e) {
        console.warn("[TW] Parse-Fehler bei ScavengeScreen-Optionen:", e);
        return null;
    }
}

function computeScavengeDuration(units, optionConfig) {
    let capacity = 0;
    for (const unit of SCAVENGE_UNIT_KEYS) {
        capacity += (units[unit] || 0) * (UNIT_STATS[unit]?.loot || 0);
    }

    const lootFactor = optionConfig.loot_factor;
    const durationExponent = optionConfig.duration_exponent;
    const durationInitialSeconds = optionConfig.duration_initial_seconds;
    const durationFactor = optionConfig.duration_factor;

    return (((lootFactor * capacity) ** 2 * 100) ** durationExponent + durationInitialSeconds) * durationFactor;
}

function computeMaxCapacityForDuration(optionConfig, maxDurationSeconds) {
    const lootFactor = optionConfig.loot_factor;
    const durationExponent = optionConfig.duration_exponent;
    const durationInitialSeconds = optionConfig.duration_initial_seconds;
    const durationFactor = optionConfig.duration_factor;

    const inner = maxDurationSeconds / durationFactor - durationInitialSeconds;
    if (inner <= 0) return 0;

    return Math.sqrt(inner ** (1 / durationExponent) / 100) / lootFactor;
}


const DEFAULT_MASS_PROFILE = {
    id: "",
    name: "Neues Profil",
    scope: "group",
    groupId: "0",
    groupName: "alle",
    villageIds: [],
    maxRuntimeHours: 3,
    runtimeMode: "duration",
    deadline: "",
    slots: [1, 2, 3, 4],
    units: null
};

function computeMassProfileRuntimeLimitSeconds(profile) {
    if (!profile) return null;
    if (profile.runtimeMode === "deadline") {
        if (!profile.deadline) return null;
        const target = new Date(profile.deadline).getTime();
        if (isNaN(target)) return null;
        return Math.max(0, (target - serverNowMs()) / 1000);
    }
    return profile.maxRuntimeHours > 0 ? profile.maxRuntimeHours * 3600 : null;
}

function loadMassProfiles() {
    const settings = Object.assign({}, DEFAULT_SETTINGS, loadSettings());
    const mm = settings.massMode || DEFAULT_SETTINGS.massMode;
    const profiles = Array.isArray(mm.profiles) ? mm.profiles : [];


    // Ohne Profil wurde bisher ein Ersatzprofil "Alle Dörfer" erzeugt.
    // Auch das hatte keine eigene Einheitenauswahl und griff auf den
    // unsichtbaren Einstellungsblock zurueck - dieselbe Falle wie beim
    // Rest-Profil, nur seltener. Statt still etwas zu tun, was niemand
    // eingetragen hat, passiert jetzt nichts und es steht im Protokoll,
    // woran es liegt.
    if (!profiles.length) {
        console.warn(
            "[TW] Massen-Raubzug: kein Profil angelegt - es wird nichts verschickt. " +
            "Lege in den Einstellungen unter Raubzug mindestens ein Profil an."
        );
        return [];
    }

    // ENTFERNT (11.08.2026): Hier wurde bisher automatisch ein Profil
    // "Rest (alle übrigen Dörfer)" angehaengt, das jedes Dorf aufgriff,
    // das kein eigenes Profil abgedeckt hatte. Das war die Quelle von
    // drei Fehlern an einem Tag:
    //
    //   1. Es hatte keine eigene Einheitenauswahl und fiel auf einen
    //      Einstellungsblock zurueck, der in der Oberflaeche gar nicht
    //      mehr gezeichnet wird - unsichtbar und nicht aenderbar. Bei
    //      Ares zog es dadurch Bogenschuetzen und Schwere Kavallerie in
    //      den Raubzug, die Rausstellen gleichzeitig ausparkte.
    //   2. Der Versuch, die Einheiten stattdessen aus den eigenen
    //      Profilen zu erben, uebertrug die Reserve eines reinen
    //      Sperrprofils (9999) auf alle Einheiten und legte 15 Doerfer
    //      still.
    //   3. Auch mit korrigierter Vererbung blieb es eine Regel, die
    //      niemand in der Oberflaeche sieht und deren Wirkung sich aus
    //      anderen Profilen ergibt.
    //
    // Die Regel lautet jetzt schlicht: Ein Dorf wird bearbeitet, wenn es
    // in einem Profil steht. Sonst nicht. Was der Nutzer nicht
    // eingetragen hat, passiert auch nicht.
    return profiles.map(p => Object.assign({}, DEFAULT_MASS_PROFILE, p));
}

function loadScavengeOptionsConfig() {
    try {
        const raw = localStorage.getItem("tw_scavenge_options_config");
        return raw ? JSON.parse(raw) : null;
    } catch (e) {
        return null;
    }
}

